SearchHandlerAsyncWaiter::SearchHandlerAsyncWaiter(
    SearchHandler* proxy) : proxy_(proxy) {}

SearchHandlerAsyncWaiter::~SearchHandlerAsyncWaiter() = default;

void SearchHandlerAsyncWaiter::Search(
    const ::std::u16string& query, uint32_t max_num_results, ParentResultBehavior parent_result_behavior, std::vector<SearchResultPtr>* out_results) {
  base::RunLoop loop;
  proxy_->Search(std::move(query),std::move(max_num_results),std::move(parent_result_behavior),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<SearchResultPtr>* out_results
,
             std::vector<SearchResultPtr> results) {*out_results = std::move(results);
            loop->Quit();
          },
          &loop,
          out_results));
  loop.Run();
}

std::vector<SearchResultPtr> SearchHandlerAsyncWaiter::Search(
    const ::std::u16string& query, uint32_t max_num_results, ParentResultBehavior parent_result_behavior) {
  std::vector<SearchResultPtr> async_wait_result;
  Search(std::move(query),std::move(max_num_results),std::move(parent_result_behavior),&async_wait_result);
  return async_wait_result;
}






